#!/usr/bin/env node
// Condense a Claude Code JSONL conversation log for reading.
// usage: node render.mjs <file> [maxTextChars]
import { readFileSync } from 'node:fs';
const [file, maxRaw] = process.argv.slice(2);
const MAX = Number(maxRaw || 700);
const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);
let t0 = null;
const clip = (s) => {
  s = String(s ?? '').replace(/\s+/g, ' ').trim();
  return s.length > MAX ? s.slice(0, MAX) + ` …[${s.length}]` : s;
};
for (const line of lines) {
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp ? new Date(e.timestamp) : null;
  if (ts && !t0) t0 = ts;
  const rel = ts ? `+${String(Math.round((ts - t0) / 1000)).padStart(5)}s` : '      ';
  const type = e.type || (e.attachment ? `attach:${e.attachment.type}` : '?');
  const msg = e.message;
  if (!msg) { console.log(`${rel} [${type}] ${clip(JSON.stringify(e).slice(0, 300))}`); continue; }
  const role = msg.role;
  const content = Array.isArray(msg.content) ? msg.content : [{ type: 'text', text: msg.content }];
  for (const c of content) {
    if (c.type === 'text') console.log(`${rel} <${role}> ${clip(c.text)}`);
    else if (c.type === 'thinking') console.log(`${rel} <think> ${clip(c.thinking)}`);
    else if (c.type === 'tool_use') console.log(`${rel} <tool:${c.name}> ${clip(JSON.stringify(c.input))}`);
    else if (c.type === 'tool_result') {
      const body = typeof c.content === 'string' ? c.content : JSON.stringify(c.content);
      console.log(`${rel} <result${c.is_error ? ':ERR' : ''}> ${clip(body).slice(0, 400)}`);
    } else console.log(`${rel} <${c.type}> ${clip(JSON.stringify(c)).slice(0, 200)}`);
  }
}

