#!/usr/bin/env node
// Condense a Claude Code JSONL log: sidechain marker, relative wall-clock, role/tool.
// usage: node render2.mjs <file> [maxChars]
import { readFileSync } from 'node:fs';
const [file, maxRaw] = process.argv.slice(2);
const MAX = Number(maxRaw || 400);
let t0 = null;
const clip = (s) => {
  s = String(s ?? '').replace(/\s+/g, ' ').trim();
  return s.length > MAX ? s.slice(0, MAX) + ` …[${s.length}]` : s;
};
for (const line of readFileSync(file, 'utf8').split('\n').filter(Boolean)) {
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp ? new Date(e.timestamp) : null;
  if (ts && !t0) t0 = ts;
  const rel = ts ? `+${String(Math.round((ts - t0) / 1000)).padStart(5)}s` : '      ';
  const side = e.isSidechain ? 'SUB' : 'par';
  const msg = e.message;
  if (!msg) continue;
  const role = msg.role;
  const content = Array.isArray(msg.content) ? msg.content : [{ type: 'text', text: msg.content }];
  for (const c of content) {
    if (c.type === 'text') console.log(`${side} ${rel} <${role}> ${clip(c.text)}`);
    else if (c.type === 'tool_use') console.log(`${side} ${rel} <tool:${c.name}> ${clip(JSON.stringify(c.input))}`);
    else if (c.type === 'tool_result') {
      const body = typeof c.content === 'string' ? c.content : JSON.stringify(c.content);
      console.log(`${side} ${rel} <res${c.is_error ? ':ERR' : ''}> ${clip(body)}`);
    }
  }
}

